<?php namespace ProcessWire;

/**
 * Video Files: class names of Bulma for videos on the website
 *
 * Choose it in the settings of the module "Video Files" (CSS framework of the website), or
 * for a single video: $video->render([ 'framework' => 'bulma1' ]). The module does not load
 * Bulma. Your website has to include its stylesheet. Made for Bulma 1; the class names it
 * uses are in Bulma 0.9 as well.
 *
 * To change this profile, do not edit this file: it is replaced with every update of the
 * module. Create /site/templates/selfhostedvideo/frameworks/bulma1.php instead, which is then
 * used in place of this file. It can name only what it changes:
 *
 *     return array(
 *         'extends' => 'bulma1',
 *         'parts' => array(
 *             'caption' => 'mt-2 has-text-centered',
 *             'title' => false,  // false: this part is left to the module again
 *         ),
 *     );
 *
 * The format of a profile is explained in the head of uikit3.php and under "CSS frameworks"
 * in the README, which also lists all parts.
 *
 * This file is part of the FieldtypeSelfHostedVideo module for ProcessWire 3.x
 *
 */

if(!defined("PROCESSWIRE")) die();

return array(

	'title' => 'Bulma 1',

	'parts' => array(

		// a video with controls: a block, with Bulma's space below it
		'player' => 'block',

		// Overlays: text and links on the picture, in Bulma's colours. They keep the shape the
		// module gives them ('look' => true); Bulma's colour helpers decide the colours all the same.
		'overlay-dark' => array('class' => 'has-background-dark has-text-white', 'look' => true),
		'overlay-light' => array('class' => 'has-background-white has-text-black', 'look' => true),

		// The list of chapters below the video: a menu. The chapter being played is its active item.
		// With Bulma 0.9 the grey of a menu label is a little lighter than accessibility guidelines
		// ask for; there, 'chapters-label' => 'has-text-weight-bold mb-2' is the safer choice.
		'chapters' => 'menu mt-4',
		'chapters-label' => 'menu-label',
		'chapter-list' => 'menu-list',
		'chapter' => array('class' => 'is-flex', 'current' => 'is-active'),

		// title, duration and description below the video
		'caption' => 'mt-2',
		'title' => 'has-text-weight-bold is-size-5',
		'meta' => 'is-size-7', // in the colour of the text: Bulma's greys are too pale on one of its themes
		'description' => 'is-size-7',

		// More about the video (the custom fields, in a box that opens): Bulma's box, white with a
		// shadow. It stays the browser's own details element, the list keeps the module's look.
		'info' => 'box p-3 mt-4',
		'transcript' => 'box p-3 mt-4',
		'transcript-body' => 'mt-2',
		'info-term' => 'has-text-weight-semibold',

		// The two buttons on the picture (full screen, pause of a background video) keep the look
		// of the module: white on black with a white ring, which can be seen on any picture.
		// To make them Bulma buttons all the same:
		// 'fullscreen' => 'button is-dark',
		// 'toggle' => 'button is-dark',
	),
);
